      "source": "https://dict.thinktrader.net/nativeApi/xttrader.html#%E8%82%A1%E7%A5%A8%E5%BC%82%E6%AD%A5%E6%92%A4%E5%8D%95-1",
      "example": "import time\nfrom cfquant import xtconstant\nfrom cfquant.xttrader import XtQuantTrader, XtQuantTraderCallback\nfrom cfquant.xttype import StockAccount\n\nclass Callback(XtQuantTraderCallback):\n    def on_cancel_order_stock_async_response(self, data):\n        print(\"on_cancel_order_stock_async_response\")\n        print(getattr(data, \"seq\", None),\n              getattr(data, \"order_id\", None),\n              getattr(data, \"cancel_result\", None))\n\naccount = StockAccount(\"YOUR_ACCOUNT_ID\", \"STOCK\")\ntrader = XtQuantTrader(\"\", int(time.time()))\ntry:\n    trader.register_callback(Callback())\n    trader.start()\n    if trader.connect() != 0:\n        raise RuntimeError(\"cfquant bridge connection failed\")\n    if trader.subscribe(account) != 0:\n        raise RuntimeError(\"account subscription failed\")\n    ENABLE_CANCEL = False\n    TARGET_ORDER_ID = \"YOUR_ORDER_ID\"\n    orders = trader.query_stock_orders(account, cancelable_only=True) or []\n    target = next((o for o in orders if str(o.order_id) == TARGET_ORDER_ID), None)\n    if target is None:\n        raise RuntimeError(\"Target is not in this account cancellable orders\")\n    if not ENABLE_CANCEL:\n        raise RuntimeError(\"Confirm this order before enabling cancellation\")\n    sysid = getattr(target, \"order_sysid\", \"\")\n    if not sysid:\n        raise RuntimeError(\"Missing confirmed counter order identifier\")\n    # This example is limited to a confirmed SH-market order.\n    if not target.stock_code.endswith(\".SH\"):\n        raise RuntimeError(\"Market does not match this example\")\n    result = trader.cancel_order_stock_sysid_async(account, market=xtconstant.SH_MARKET, sysid=sysid)\n    print(\"cancel request result:\", result)\n    trader.run_forever()\nexcept KeyboardInterrupt:\n    pass\nfinally:\n    trader.stop()",
      "originalExample": "import time\nfrom xtquant import xtconstant\nfrom xtquant.xttrader import XtQuantTrader, XtQuantTraderCallback\nfrom xtquant.xttype import StockAccount\n\nclass Callback(XtQuantTraderCallback):\n    def on_cancel_order_stock_async_response(self, data):\n        print(\"on_cancel_order_stock_async_response\")\n        print(getattr(data, \"seq\", None),\n              getattr(data, \"order_id\", None),\n              getattr(data, \"cancel_result\", None))\n\naccount = StockAccount(\"YOUR_ACCOUNT_ID\", \"STOCK\")\ntrader = XtQuantTrader(r\"D:\\QMT\\userdata_mini\", int(time.time()))\ntry:\n    trader.register_callback(Callback())\n    trader.start()\n    if trader.connect() != 0:\n        raise RuntimeError(\"MiniQMT connection failed\")\n    if trader.subscribe(account) != 0:\n        raise RuntimeError(\"account subscription failed\")\n    ENABLE_CANCEL = False\n    TARGET_ORDER_ID = \"YOUR_ORDER_ID\"\n    orders = trader.query_stock_orders(account, cancelable_only=True) or []\n    target = next((o for o in orders if str(o.order_id) == TARGET_ORDER_ID), None)\n    if target is None:\n        raise RuntimeError(\"Target is not in this account cancellable orders\")\n    if not ENABLE_CANCEL:\n        raise RuntimeError(\"Confirm this order before enabling cancellation\")\n    sysid = getattr(target, \"order_sysid\", \"\")\n    if not sysid:\n        raise RuntimeError(\"Missing confirmed counter order identifier\")\n    # This example is limited to a confirmed SH-market order.\n    if not target.stock_code.endswith(\".SH\"):\n        raise RuntimeError(\"Market does not match this example\")\n    result = trader.cancel_order_stock_sysid_async(account, market=xtconstant.SH_MARKET, order_sysid=sysid)\n    print(\"cancel request result:\", result)\n    trader.run_forever()\nexcept KeyboardInterrupt:\n    pass\nfinally:\n    trader.stop()",
      "usage": "示例运行前需完成 Web 账号绑定，并在大 QMT 中启动对应桥策略。 示例默认禁止撤单。撤单返回值表示请求结果，最终状态需核对委托回报。",
      "resultHelp": "异步形式返回请求序号，通过撤单应答与委托事件确认结果；同步形式返回撤单请求结果，最终是否撤成仍以委托状态为准。"
